import re
L=open('Ern/MemoryModel/Access/Preserve/Small.lean',encoding='utf8').read().split('\n')
for i,l in enumerate(L):
    if re.match(r'^(private )?(theorem|def|lemma|instance|structure|inductive|abbrev)\b',l):
        j=i-1
        # find docstring end above
        ok=False
        while j>=0 and L[j].strip()!='' :
            if '-/' in L[j]:
                # check doc contains §
                k=j
                doc=[]
                while k>=0:
                    doc.append(L[k])
                    if '/--' in L[k]: break
                    k-=1
                ok='§' in ''.join(doc)
                break
            j-=1
        if not ok: print('NO DOC/§:',i+1,l)
    if len(l)>100: print('LONG',i+1)
EOF

